"""CPU, standard-library-only multidimensional array.

A :class:`Tensor` is a nested ``list`` of Python floats with an immutable
shape.  Parameter tensors carry an accumulating :attr:`grad`; activation
tensors carry no gradient history.  All arithmetic goes through
:mod:`operator` calls on plain Python floats, so parameter updates computed
from the same gradient values are bit-for-bit identical regardless of where
the gradient came from.
"""

import operator


def _validate_data(data):
    """Return ``(flat_floats, shape)`` for a valid nested numeric ``list``.

    Raises :class:`ValueError` for empty data, ragged nesting, booleans and
    non-numeric leaves.  Integers are accepted and widened to ``float``.
    """
    if not isinstance(data, list):
        raise ValueError("Tensor data must be a nested list of numbers")
    if len(data) == 0:
        raise ValueError("Tensor data must not be empty")

    flat = []
    shape = []
    ragged = [False]

    def walk(node, depth):
        if isinstance(node, list):
            if len(node) == 0:
                raise ValueError("Tensor data must not contain empty lists")
            if depth == len(shape):
                shape.append(len(node))
            elif len(node) != shape[depth]:
                ragged[0] = True
                return
            for child in node:
                walk(child, depth + 1)
        else:
            # ``bool`` is a subclass of ``int``; reject it explicitly.
            if isinstance(node, bool) or not isinstance(node, (int, float)):
                raise ValueError(
                    "Tensor leaves must be int or float, "
                    f"not {type(node).__name__}"
                )
            flat.append(float(node))

    walk(data, 0)
    if ragged[0]:
        raise ValueError("Tensor data must have a rectangular shape")
    return flat, shape


class Tensor:
    """Nested-list tensor with an optional :attr:`grad` accumulator."""

    def __init__(self, data):
        flat, shape = _validate_data(data)
        self._flat = flat
        self._shape = tuple(shape)
        self._grad = None

    # -- constructors used inside the engine --------------------------------

    @classmethod
    def _from_flat(cls, flat, shape):
        """Build a tensor directly from a flat list of floats."""
        self = cls.__new__(cls)
        self._flat = list(flat)
        self._shape = tuple(shape)
        self._grad = None
        return self

    @classmethod
    def zeros(cls, shape):
        """Return an all-zero tensor with the given non-empty shape."""
        shape = tuple(shape)
        if len(shape) == 0 or any(size <= 0 for size in shape):
            raise ValueError("Tensor shape must be non-empty and positive")
        return cls._from_flat([0.0] * _product(shape), shape)

    # -- public surface ------------------------------------------------------

    @property
    def shape(self):
        return list(self._shape)

    def tolist(self):
        """Return a nested ``list`` copy of the tensor's values."""
        return _nest(self._flat, self._shape)

    @property
    def grad(self):
        """Accumulated parameter gradient (a :class:`Tensor`) or ``None``."""
        return self._grad

    # -- gradient accumulation ----------------------------------------------

    def _zero_grad(self):
        self._grad = None

    def _accumulate_grad(self, other):
        """Add ``other`` to this tensor's gradient with ordinary float add.

        Gradient contributions are accumulated in call order, i.e. in reverse
        time for a chunk.  Plain ``float.__add__`` is used, so the same
        sequence of gradient values always yields the same accumulator.
        """
        flat = other._flat
        if self._grad is None:
            self._grad = Tensor._from_flat(list(flat), self._shape)
        else:
            acc = self._grad._flat
            for i in range(len(acc)):
                acc[i] = acc[i] + flat[i]

    # -- elementwise arithmetic ---------------------------------------------

    def _binop(self, other, op):
        if isinstance(other, Tensor):
            if other._shape != self._shape:
                raise ValueError(
                    f"shape mismatch: {self._shape} vs {other._shape}"
                )
            flat = [op(a, b) for a, b in zip(self._flat, other._flat)]
            return Tensor._from_flat(flat, self._shape)
        scalar = float(other)
        flat = [op(a, scalar) for a in self._flat]
        return Tensor._from_flat(flat, self._shape)

    def __add__(self, other):
        return self._binop(other, operator.add)

    def __radd__(self, other):
        return self._binop(other, operator.add)

    def __sub__(self, other):
        return self._binop(other, operator.sub)

    def __mul__(self, other):
        return self._binop(other, operator.mul)

    def __rmul__(self, other):
        return self._binop(other, operator.mul)

    def __truediv__(self, other):
        return self._binop(other, operator.truediv)

    def __neg__(self):
        return Tensor._from_flat([-a for a in self._flat], self._shape)

    # -- linear algebra ------------------------------------------------------

    def matmul(self, other):
        """Matrix / matrix-vector product over the last two dims.

        Supports ``(M, K) @ (K, N)`` and ``(B, M, K) @ (K, N)``.
        """
        a_shape = self._shape
        b_shape = other._shape
        if len(a_shape) < 2 or len(b_shape) != 2 or a_shape[-1] != b_shape[0]:
            raise ValueError(
                f"cannot matmul shapes {list(a_shape)} and {list(b_shape)}"
            )
        batch = a_shape[:-2]
        m, k = a_shape[-2], a_shape[-1]
        n = b_shape[1]
        a = self._flat
        b = other._flat
        out = [0.0] * (_product(batch) * m * n)
        _matmul_into(a, b, out, batch, m, k, n)
        return Tensor._from_flat(out, batch + (m, n))

    # -- broadcasting helpers used by layers --------------------------------

    def _sum_axes(self, axes):
        """Sum over the given leading axes, keeping remaining dims.

        Used to fold a batch out of a parameter gradient.  ``axes`` must name
        a prefix of the shape (in any order).
        """
        keep = [d for d in range(len(self._shape)) if d not in axes]
        out_shape = tuple(self._shape[d] for d in keep)
        out = [0.0] * _product(out_shape)
        if not axes:
            return Tensor._from_flat(list(self._flat), self._shape)
        stride_keep = [1] * len(self._shape)
        for d in range(len(self._shape) - 2, -1, -1):
            stride_keep[d] = stride_keep[d + 1] * self._shape[d + 1]
        stride_out = [1] * len(keep)
        for j in range(len(keep) - 2, -1, -1):
            stride_out[j] = stride_out[j + 1] * out_shape[j + 1]
        flat = self._flat
        for idx, value in enumerate(flat):
            o = 0
            rem = idx
            pos = 0
            for d in range(len(self._shape) - 1, -1, -1):
                coord = rem // stride_keep[d]
                rem -= coord * stride_keep[d]
                if d in axes_set := set(axes):
                    continue
                o += coord * stride_out[pos]
                pos += 1
            out[o] += value
        return Tensor._from_flat(out, out_shape)

    def _broadcast_add(self, bias):
        """Add a trailing-shape ``bias`` across every leading batch axis."""
        a_shape = self._shape
        b_shape = bias._shape
        if a_shape[-len(b_shape):] != b_shape:
            raise ValueError(
                f"cannot broadcast {list(b_shape)} into {list(a_shape)}"
            )
        repeat = _product(a_shape[:-len(b_shape)]) if len(a_shape) > len(b_shape) else 1
        tile = list(bias._flat)
        flat = []
        for _ in range(repeat):
            flat.extend(tile)
        return Tensor._from_flat(flat, a_shape)


def _product(shape):
    total = 1
    for size in shape:
        total *= size
    return total


def _nest(flat, shape):
    if len(shape) == 1:
        return list(flat)
    step = _product(shape[1:])
    return [
        _nest(flat[i * step:(i + 1) * step], shape[1:])
        for i in range(shape[0])
    ]


def _matmul_into(a, b, out, batch, m, k, n):
    batch_size = _product(batch)
    for bi in range(batch_size):
        a0 = bi * m * k
        o0 = bi * m * n
        for i in range(m):
            ar = a0 + i * k
            orow = o0 + i * n
            for kk in range(k):
                aik = a[ar + kk]
                br = kk * n
                for j in range(n):
                    out[orow + j] += aik * b[br + j]

